CREATE TABLE IF NOT EXISTS circulation_lock(id INT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS card_sequences(yr INT PRIMARY KEY, next_no INT NOT NULL);
CREATE TABLE IF NOT EXISTS readers(reader_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,identity_no VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,department VARCHAR(150) NOT NULL,contact VARCHAR(100),reader_type VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS librarians(librarian_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,employee_no VARCHAR(50) NOT NULL UNIQUE,status VARCHAR(20) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS system_admins(admin_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,employee_no VARCHAR(50) NOT NULL UNIQUE,status VARCHAR(20) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS borrow_cards(card_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,card_no VARCHAR(20) NOT NULL UNIQUE,reader_id BIGINT NOT NULL REFERENCES readers(reader_id),holder_name VARCHAR(100) NOT NULL,department VARCHAR(150) NOT NULL,status VARCHAR(20) DEFAULT 'ACTIVE',issued_at DATE NOT NULL,expires_at DATE NOT NULL,deleted_at TIMESTAMP,active_reader_id BIGINT UNIQUE REFERENCES readers(reader_id),CHECK(expires_at>=issued_at));
CREATE TABLE IF NOT EXISTS book_titles(title_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(300) NOT NULL,authors VARCHAR(500) NOT NULL,isbn_or_standard_no VARCHAR(50) UNIQUE,publisher VARCHAR(200),language VARCHAR(30) NOT NULL,item_type VARCHAR(30) NOT NULL,status VARCHAR(20) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS library_items(item_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title_id BIGINT NOT NULL REFERENCES book_titles(title_id),barcode VARCHAR(80) NOT NULL UNIQUE,item_type VARCHAR(30) NOT NULL,language VARCHAR(30) NOT NULL,loan_eligibility VARCHAR(20) NOT NULL,location VARCHAR(100) NOT NULL,status VARCHAR(20) DEFAULT 'AVAILABLE');
CREATE TABLE IF NOT EXISTS borrow_policies(policy_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reader_type VARCHAR(30) NOT NULL,max_active_loans INT NOT NULL CHECK(max_active_loans>0),loan_period_days INT NOT NULL CHECK(loan_period_days>0),effective_from TIMESTAMP DEFAULT CURRENT_TIMESTAMP,effective_to TIMESTAMP,version VARCHAR(40) NOT NULL UNIQUE,status VARCHAR(20) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS fine_rules(rule_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_type VARCHAR(30) NOT NULL,daily_rate DECIMAL(10,2) NOT NULL CHECK(daily_rate>=0),maximum_amount DECIMAL(10,2) NOT NULL CHECK(maximum_amount>=0),effective_from TIMESTAMP DEFAULT CURRENT_TIMESTAMP,effective_to TIMESTAMP,version VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS loans(loan_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reader_id BIGINT NOT NULL REFERENCES readers(reader_id),card_id BIGINT NOT NULL REFERENCES borrow_cards(card_id),item_id BIGINT NOT NULL REFERENCES library_items(item_id),librarian_id BIGINT NOT NULL REFERENCES librarians(librarian_id),return_librarian_id BIGINT REFERENCES librarians(librarian_id),borrowed_at DATE NOT NULL,due_at DATE NOT NULL,returned_at DATE,status VARCHAR(20) DEFAULT 'BORROWED',policy_version VARCHAR(40) NOT NULL,borrow_policy_id BIGINT NOT NULL REFERENCES borrow_policies(policy_id),fine_rule_id BIGINT NOT NULL REFERENCES fine_rules(rule_id),daily_rate DECIMAL(10,2) NOT NULL,maximum_amount DECIMAL(10,2) NOT NULL,active_item_id BIGINT UNIQUE REFERENCES library_items(item_id),CHECK(due_at>=borrowed_at),CHECK(returned_at IS NULL OR returned_at>=borrowed_at));
CREATE TABLE IF NOT EXISTS reservations(reservation_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reader_id BIGINT NOT NULL REFERENCES readers(reader_id),title_id BIGINT NOT NULL REFERENCES book_titles(title_id),queue_no BIGINT NOT NULL,status VARCHAR(20) DEFAULT 'WAITING',created_at TIMESTAMP NOT NULL,item_id BIGINT REFERENCES library_items(item_id),hold_until DATE,active_key VARCHAR(100) UNIQUE,UNIQUE(title_id,queue_no));
CREATE TABLE IF NOT EXISTS fine_records(fine_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,loan_id BIGINT NOT NULL UNIQUE REFERENCES loans(loan_id),overdue_days INT NOT NULL CHECK(overdue_days>=0),amount DECIMAL(10,2) NOT NULL CHECK(amount>=0),rule_version VARCHAR(40) NOT NULL,status VARCHAR(20) DEFAULT 'UNPAID',adjustment_reason VARCHAR(500),adjustment_admin_id BIGINT REFERENCES system_admins(admin_id));
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id BIGINT,role VARCHAR(30),action VARCHAR(60) NOT NULL,target VARCHAR(100),result VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_loans_reader ON loans(reader_id,returned_at);
CREATE INDEX IF NOT EXISTS ix_reservations_queue ON reservations(title_id,status,created_at,reservation_id);
CREATE INDEX IF NOT EXISTS ix_audit_actor ON audit_logs(actor_id,created_at);
